"""Deepen the 11 additional traders that previously held template filler.

Every statement is high-level, publicly documented material. Where a figure is self-reported or only
widely reported it is classified that way; nothing here is a verified audited series unless stated.
Net worth is deliberately not asserted without a dated source.
"""
from app.knowledge.schema import TraderKnowledgeProfile, SourceNote

DEEP_PROFILES: dict[str, TraderKnowledgeProfile] = {}

_NW = "No dated net-worth figure is recorded in this registry and none is asserted"
_NW_NOTE = "Add a dated Forbes/Bloomberg figure with its source when verified"


def _put(pid, name, **kw):
    kw.setdefault("net_worth", [SourceNote(_NW, "speculation", None, _NW_NOTE)])
    kw.setdefault("expandable_notes", "Deepened from public material; extend with primary sources and dated figures.")
    DEEP_PROFILES[pid] = TraderKnowledgeProfile(id=pid, full_name=name, **kw)


